<script setup lang="ts">
import {editorialProfile,profileIssue,portraitReference,sameLocalizedText} from '../../services/admin/doctorProfile';
import {scheduleErrors} from "../../services/admin/scheduleValidation";
import {clinicDate} from "../../services/booking/calendar";
import AdminSchedulesView from "./AdminSchedulesView.vue";
import DoctorPublication from "../../components/admin/DoctorPublication.vue";
import {mediaRequest} from "../../services/cms/media";
import {cmsRequest} from "../../services/cms/admin";
import {findDoc} from "../../services/cms/catalog";
import AdminMediaPreview from "../../components/admin/AdminMediaPreview.vue";
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {useI18n} from 'vue-i18n';
import {useAuthStore} from '../../stores/auth';
import {operationRequest} from '../../services/admin/operations';
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue';
import MediaLibrary from '../../components/admin/MediaLibrary.vue';
import {trapDialogFocus} from '../../services/dialogFocus';
const {t,locale}=useI18n(),route=useRoute(),router=useRouter(),auth=useAuthStore();
const resolvedID=ref(''),linkConfirmed=ref(false),tab=ref<'profile'|'services'|'schedule'>('profile'),notice=ref('');
const publication=ref<InstanceType<typeof DoctorPublication>>(),absence=ref<InstanceType<typeof AdminSchedulesView>>(),portrait=ref('');
const editorialKey=computed(()=>String(route.params.editorialKey||''));
const id=computed(()=>String(route.params.doctorID||resolvedID.value)),language=ref<'lv'|'ru'|'en'>(['lv','ru','en'].includes(locale.value)?locale.value as 'lv'|'ru'|'en':'lv');
const preparing=ref(false);
const invalidField=ref(''),invalidLocale=ref('');
const dayErrors=ref<Record<number,string>>({}),fieldError=ref(''),copyDays=ref<number[]>([]),continueTab=ref<'services'|'schedule'|null>(null);
const emptyText=()=>({lv:'',ru:'',en:''});
const blank=()=>({name:'',profile:{biography:emptyText(),qualifications:emptyText(),title:emptyText()},portrait_id:'',editorial_key:'',active:false,booking_enabled:false,sort_order:0,provenance:'clinic_verified',setup:{service_ids:[],hours:[]}});
const form=ref<any>(blank());
const scheduleMonth=ref(clinicDate().slice(0,7));
const datedHours=computed(()=>form.value.setup.hours.filter((h:any)=>isDated(h)&&(!h.effective_from||h.effective_from.startsWith(scheduleMonth.value))).sort((a:any,b:any)=>(a.effective_from||'9999').localeCompare(b.effective_from||'9999')||a.start.localeCompare(b.start)));
const rows=ref<any[]>([]),services=ref<any[]>([]),privacy=ref(false),search=ref(''),busy=ref(false),error=ref(''),version=ref(''),loaded=ref(false),baseline=ref('');
const picker=ref<HTMLDialogElement>(),picking=ref(false);let controller=new AbortController(),operationID=crypto.randomUUID();
const dirty=computed(()=>loaded.value&&(baseline.value!==JSON.stringify(form.value)||!!publication.value?.dirty||!!absence.value?.dirty));
const filtered=computed(()=>services.value.filter(s=>(s.active&&s.booking_enabled&&s.duration_minutes>0||form.value.setup.service_ids.includes(s.id))&&s['name_'+locale.value].toLowerCase().includes(search.value.toLowerCase())));
const eligible=computed(()=>services.value.some(s=>form.value.setup.service_ids.includes(s.id)&&s.active&&s.booking_enabled&&s.duration_minutes>0));
const validHours=computed(()=>form.value.setup.hours.length>0&&!Object.keys(scheduleErrors(form.value.setup.hours)).length);
const ready=computed(()=>eligible.value&&validHours.value&&privacy.value&&form.value.setup.hours.some((h:any)=>(!h.effective_until||h.effective_until>=clinicDate())&&services.value.some(s=>form.value.setup.service_ids.includes(s.id)&&s.active&&s.booking_enabled&&s.duration_minutes>0&&minute(h.end)-minute(h.start)>=s.duration_minutes)));
const days=computed(()=>[1,2,3,4,5,6,0].map(i=>({value:i,label:new Intl.DateTimeFormat(locale.value,{weekday:'long',timeZone:'Europe/Riga'}).format(new Date(Date.UTC(2026,0,4+i,12)))})));
function minute(s:string){return Number(s.slice(0,2))*60+Number(s.slice(3,5))}
let loadSerial=0;
async function load(){const serial=++loadSerial;busy.value=true;error.value='';try{const [r,o]=await Promise.all([operationRequest('/operations/doctors',controller.signal),operationRequest('/operations/doctors/options',controller.signal)]);if(serial!==loadSerial)return;rows.value=r.items;services.value=o.services||[];privacy.value=o.privacy_ready===true;if(editorialKey.value){if(editorialKey.value!=='clinic.doctorBio')throw Error();resolvedID.value=r.items.find((row:any)=>row.data.editorial_key===editorialKey.value)?.id||'';}if(id.value){const row=r.items.find((r:any)=>r.id===id.value);if(!row)throw Error();const d=row.data;form.value={name:d.name,profile:{...d.profile,title:d.profile.title||emptyText()},portrait_id:d.portrait_id||'',editorial_key:d.editorial_key||'',active:d.active,booking_enabled:d.booking_enabled,sort_order:d.sort_order,provenance:d.provenance,setup:{service_ids:d.service_ids||[],hours:(d.hours||[]).map((h:any)=>({id:h.id,weekday:h.weekday,start: h.start_time.slice(0,5),end:h.end_time.slice(0,5),effective_from:h.effective_from?.slice(0,10)||'',effective_until:h.effective_until?.slice(0,10)||''}))}};version.value=row.version}else if(editorialKey.value){const [bio,media,home]=await Promise.all([cmsRequest('/clinic.doctorBio',controller.signal),cmsRequest('/clinic.media',controller.signal),cmsRequest('/messages.home',controller.signal)]);const published=bio.revisions.find((r:any)=>r.id===(bio.document.draft_revision||bio.document.published_revision));const image=media.revisions.find((r:any)=>r.id===(media.document.draft_revision||media.document.published_revision));form.value.name=findDoc('clinic.doctorBio')!.title[locale.value as 'lv'|'ru'|'en'];Object.assign(form.value.profile,editorialProfile(published?.payload,home.revisions.find((r:any)=>r.id===(home.document.draft_revision||home.document.published_revision))?.payload));form.value.editorial_key=editorialKey.value;const library=await mediaRequest();form.value.portrait_id=portraitReference(library.assets,image?.payload.doctor);}baseline.value=JSON.stringify(form.value);loaded.value=true}catch(e){error.value=(e as Error).message==='portraitInvalid'?'portraitInvalid':'unavailable'}finally{if(serial===loadSerial)busy.value=false}}
function useExisting(event:Event){if(!discard()){(event.target as HTMLSelectElement).value=id.value;return}const value=(event.target as HTMLSelectElement).value;const row=rows.value.find(r=>r.id===value&&!r.data.editorial_key);if(!row)return;const d=row.data;resolvedID.value=row.id;version.value=row.version;form.value={name:d.name,profile:{...d.profile,title:d.profile.title||emptyText()},portrait_id:d.portrait_id||'',editorial_key:editorialKey.value,active:d.active,booking_enabled:d.booking_enabled,sort_order:d.sort_order,provenance:d.provenance,setup:{service_ids:d.service_ids||[],hours:(d.hours||[]).map((h:any)=>({id:h.id,weekday:h.weekday,start:h.start_time.slice(0,5),end:h.end_time.slice(0,5),effective_from:h.effective_from?.slice(0,10)||'',effective_until:h.effective_until?.slice(0,10)||''}))}};baseline.value=JSON.stringify({...form.value,editorial_key:d.editorial_key||''});linkConfirmed.value=false;operationID=crypto.randomUUID()}
function discard(){return !dirty.value||window.confirm(t('operations.discard'))}
function isDated(h:any){return h.single_date||!!h.effective_from&&h.effective_from===h.effective_until}
function setWorkingDate(h:any,date:string){h.effective_from=date;h.effective_until=date;if(date)scheduleMonth.value=date.slice(0,7);h.weekday=new Date(date+'T12:00:00Z').getUTCDay()}
function addWorkingDate(){form.value.setup.hours.push({id:'',weekday:0,start:'',end:'',effective_from:'',effective_until:'',single_date:true})}
function toggleDay(day:number,on:boolean){if(on)form.value.setup.hours.push({id:'',weekday:day,start:'',end:'',effective_from:'',effective_until:''});else form.value.setup.hours=form.value.setup.hours.filter((h:any)=>h.weekday!==day||isDated(h))}
function addHour(day:number){form.value.setup.hours.push({id:'',weekday:day,start:'',end:'',effective_from:'',effective_until:''})}
function copyMonday(){const source=form.value.setup.hours.filter((h:any)=>h.weekday===1&&!isDated(h));dayErrors.value=scheduleErrors(source);if(!source.length||Object.keys(dayErrors.value).length||!copyDays.value.length)return;if(!window.confirm(t('specialist.copyConfirm')))return;form.value.setup.hours=form.value.setup.hours.filter((h:any)=>!copyDays.value.includes(h.weekday)||isDated(h));for(const day of copyDays.value)for(const h of source)form.value.setup.hours.push({...h,id:'',weekday:day});copyDays.value=[]}
async function saveContinue(){continueTab.value=tab.value==='schedule'?'schedule':'services';tab.value='profile';await save()}
function selectTab(value:'profile'|'services'|'schedule'){tab.value=value;notice.value=''}
function moveTab(event:KeyboardEvent){const tabs=['profile','services','schedule'] as const;let index=tabs.indexOf(tab.value);if(event.key==='ArrowRight')index=(index+1)%3;else if(event.key==='ArrowLeft')index=(index+2)%3;else if(event.key==='Home')index=0;else if(event.key==='End')index=2;else return;event.preventDefault();selectTab(tabs[index]!);document.getElementById('tab-'+tab.value)?.focus()}
async function save(activation?:boolean){
 if(busy.value||preparing.value||!auth.verifiedAdmin||publication.value?.busy)return;
 error.value='';notice.value='';fieldError.value='';invalidField.value='';invalidLocale.value='';dayErrors.value={};
 if(activation===true&&(!ready.value||dirty.value)){error.value='setupError';return}
 if(activation===undefined&&!form.value.name.trim()){fieldError.value='nameRequired';tab.value='profile';return}
 if(activation===undefined&&tab.value==='profile'){
  if(form.value.editorial_key){if(!publication.value?.loaded)return;const snapshot=publication.value.snapshot();for(const field of ['biography','title'] as const)if(!sameLocalizedText(form.value.profile[field],snapshot[field]))form.value.profile[field]=snapshot[field];preparing.value=true;try{form.value.portrait_id=portraitReference((await mediaRequest('', 'GET',controller.signal)).assets,snapshot.portrait)}catch(e){if((e as Error).message==='portraitInvalid'){fieldError.value='portraitInvalid';invalidField.value='portrait'}else error.value='unavailable';return}finally{preparing.value=false}}
  const issue=profileIssue(form.value.profile);if(issue){fieldError.value='profileFieldInvalid';invalidField.value=issue.field;invalidLocale.value=issue.locale||'';if(issue.locale)language.value=issue.locale as 'lv'|'ru'|'en';return}
 }
 if(activation===undefined&&tab.value==='schedule'){if(form.value.setup.hours.some((h:any)=>isDated(h)&&!h.effective_from)){error.value='setupError';return}dayErrors.value=scheduleErrors(form.value.setup.hours);if(Object.keys(dayErrors.value).length)return}
 const needsLink=!!form.value.editorial_key&&!linkConfirmed.value&&(!id.value||!rows.value.find(r=>r.id===id.value)?.data.editorial_key);
 const consent=t(activation===true?'specialist.confirmEnable':activation===false?'specialist.confirmDisable':'specialist.confirmSave')+(needsLink?'\n\n'+t('doctors.linkConfirmation'):'');
 if(!window.confirm(consent))return;
 if(needsLink)linkConfirmed.value=true;
 busy.value=true;let savedOperation=false;
 try{
  const next=JSON.parse(baseline.value);
  if(activation!==undefined){next.active=activation?true:next.active;next.booking_enabled=activation}
  else if(tab.value==='profile'){for(const key of ['name','profile','portrait_id','editorial_key'])next[key]=JSON.parse(JSON.stringify(form.value[key]))}
  else if(tab.value==='services')next.setup.service_ids=[...form.value.setup.service_ids];
  else next.setup.hours=JSON.parse(JSON.stringify(form.value.setup.hours));
  if(!id.value||JSON.stringify(next)!==baseline.value){
   const data={...next,confirm_editorial_link:linkConfirmed.value,setup:{...next.setup,hours:next.setup.hours.map((h:any)=>({id:h.id,weekday:h.weekday,start_minute:minute(h.start),end_minute:minute(h.end),effective_from:h.effective_from,effective_until:h.effective_until}))}};
   const row=await operationRequest('/operations/doctors'+(id.value?'/'+id.value:''),controller.signal,{operation_id:operationID,expected_version:version.value,data},id.value?'PUT':'POST');
   if(row.data?.hours&&tab.value==='schedule'&&activation===undefined){next.setup.hours=row.data.hours.map((h:any)=>({id:h.id,weekday:h.weekday,start:h.start_time.slice(0,5),end:h.end_time.slice(0,5),effective_from:h.effective_from?.slice(0,10)||'',effective_until:h.effective_until?.slice(0,10)||''}));form.value.setup.hours=JSON.parse(JSON.stringify(next.setup.hours))}
   baseline.value=JSON.stringify(next);version.value=row.version;operationID=crypto.randomUUID();savedOperation=true;
   if(activation!==undefined){form.value.active=next.active;form.value.booking_enabled=next.booking_enabled}
   if(!id.value){resolvedID.value=row.id;skipRouteReload=true;await router.replace('/admin/doctors/manage/'+row.id)}
  }
  if(activation===undefined&&tab.value==='profile'&&publication.value&&!await publication.value.saveDrafts()){error.value=savedOperation?'partial':'unavailable';return}
  notice.value=t(activation!==undefined?'specialist.saved':tab.value==='schedule'?'specialist.scheduleSaved':'specialist.saved');if(continueTab.value&&id.value){tab.value=continueTab.value;continueTab.value=null}
 }catch(e){const code=(e as Error).message;if(code==='notReady'){fieldError.value='bookingRequirements'}else if(code==='invalid'&&(e as any).validation){if(Number.isInteger((e as any).day)&&(e as any).day>=0&&(e as any).day<=6){dayErrors.value[(e as any).day]=(e as any).validation;tab.value='schedule'}else{fieldError.value=(e as any).validation;invalidField.value=(e as any).field||'';invalidLocale.value=(e as any).locale||'';if(['lv','ru','en'].includes(invalidLocale.value))language.value=invalidLocale.value as 'lv'|'ru'|'en';tab.value='profile'}}else if(code==='invalid'){fieldError.value=tab.value==='schedule'?'scheduleRejected':tab.value==='services'?'servicesRejected':'profileRejected'}else{error.value=['conflict','impact'].includes(code)?code:'unavailable';if(code==='impact'&&tab.value==='schedule'){const old=JSON.parse(baseline.value).setup.hours;for(const day of days.value)if(JSON.stringify(old.filter((h:any)=>h.weekday===day.value&&!isDated(h)))!==JSON.stringify(form.value.setup.hours.filter((h:any)=>h.weekday===day.value&&!isDated(h))))dayErrors.value[day.value]='impactSchedule'}}}finally{busy.value=false}
}
let skipRouteReload=false;
function select(asset:any){form.value.portrait_id=asset.id;picking.value=false;picker.value?.close()}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(()=>auth.verifiedAdmin,value=>{if(value&&!loaded.value&&!busy.value)void load()},{immediate:true});
onBeforeRouteLeave(discard);onBeforeRouteUpdate(()=>skipRouteReload||discard());watch(()=>[route.params.doctorID,route.params.editorialKey],()=>{if(skipRouteReload){skipRouteReload=false;return}tab.value='profile';resolvedID.value='';linkConfirmed.value=false;form.value=blank();baseline.value='';loaded.value=false;version.value='';operationID=crypto.randomUUID();void load()});window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{controller.abort();window.removeEventListener('beforeunload',unload)});
</script>
<template><section class="doctor-setup"><header class="doctor-heading"><AdminMediaPreview v-if="portrait||form.portrait_id" :reference="portrait||form.portrait_id"/><AdminPageHeader :title="form.name||t('simple.addDoctor')"/></header><RouterLink to="/admin/doctors">{{t('simple.back')}}</RouterLink>
<p class="feedback" role="status">{{busy?t('operations.loading'):notice}}</p><p v-if="error" role="alert">{{t(error==='portraitInvalid'?'specialist.portraitInvalid':error==='partial'?'specialist.partial':error==='conflict'?'specialist.savedElsewhere':error==='setupError'?'simple.setupError':error==='impact'?'specialist.impactSchedule':'operations.'+error,{count:1})}} <button v-if="error==='conflict'" type="button" @click="()=>{if(discard())load()}">{{t('specialist.reload')}}</button></p>
<template v-if="loaded"><div class="editor-tabs" role="tablist" :aria-label="t('doctors.information')" @keydown="moveTab"><button v-for="item in ['profile','services','schedule'] as const" :id="'tab-'+item" :key="item" role="tab" :aria-selected="tab===item" :aria-controls="'panel-'+item" :tabindex="tab===item?0:-1" @click="selectTab(item)">{{t('specialist.'+item)}}</button></div>
<p v-if="!id&&tab!=='profile'">{{t('specialist.saveFirstAction')}} <button type="button" :disabled="busy" @click="saveContinue">{{t('specialist.saveContinue')}}</button></p>
<p v-if="dirty" class="draft-hint">{{t('specialist.unsaved')}}</p>
<form novalidate @submit.prevent="save()"><p v-if="fieldError" id="doctor-field-error" role="alert">{{t('specialist.'+fieldError,{field:invalidField?t((invalidField==='title'?'doctors.':'operations.')+invalidField):'',locale:invalidLocale.toUpperCase()})}}</p><fieldset id="panel-profile" v-show="tab==='profile'" role="tabpanel" aria-labelledby="tab-profile" :disabled="busy||tab!=='profile'"><label>{{t('operations.doctorName')}}<input v-model="form.name" :aria-invalid="fieldError==='nameRequired'" aria-describedby="doctor-field-error" required maxlength="200" autocomplete="off"/></label>
<label>{{t('created.language')}}<select v-model="language"><option v-for="l in ['lv','ru','en']" :key="l" :value="l">{{l.toUpperCase()}}</option></select></label>
<DoctorPublication v-if="form.editorial_key" ref="publication" :blocked="baseline!==JSON.stringify(form)" :language="language" :invalid-field="invalidField" :invalid-locale="invalidLocale" @portrait="portrait=$event"/>
<template v-else><button type="button" @click="()=>{picking=true;picker?.showModal()}">{{t('operations.portrait')}}</button><button v-if="form.portrait_id" type="button" @click="form.portrait_id=''">{{t('operations.removePortrait')}}</button><label>{{t('doctors.title')}}<input v-model="form.profile.title[language]" :aria-invalid="invalidField==='title'" aria-describedby="doctor-field-error" maxlength="2000"/></label><label>{{t('operations.biography')}}<textarea v-model="form.profile.biography[language]" :aria-invalid="invalidField==='biography'" aria-describedby="doctor-field-error" maxlength="4000" rows="6"/></label></template>
<details v-if="editorialKey&&!id&&rows.some(r=>!r.data.editorial_key)"><summary>{{t('specialist.more')}}</summary><label>{{t('doctors.existing')}}<select :aria-label="t('doctors.existing')" @change="useExisting"><option value="">{{t('operations.choose')}}</option><option v-for="r in rows.filter(r=>!r.data.editorial_key)" :key="r.id" :value="r.id">{{r.data.name}}</option></select></label></details>
</fieldset>
<fieldset id="panel-services" v-show="tab==='services'&&!!id" role="tabpanel" aria-labelledby="tab-services" :disabled="busy||tab!=='services'||!id"><p v-if="!services.some(s=>s.active&&s.booking_enabled&&s.duration_minutes>0)">{{t('specialist.noServices')}}</p><label v-else-if="services.length>8">{{t('simple.searchServices')}}<input v-model="search" type="search"/></label><label v-for="s in filtered" :key="s.id" class="service-check"><input v-model="form.setup.service_ids" type="checkbox" :value="s.id"/>{{s['name_'+locale]}}</label></fieldset>
<fieldset id="panel-schedule" v-show="tab==='schedule'&&!!id" role="tabpanel" aria-labelledby="tab-schedule" :disabled="busy||tab!=='schedule'||!id"><p>{{t('operations.riga')}}</p><section class="individual-dates"><h3>{{t('specialist.individualDates')}}</h3><p>{{t('specialist.individualHelp')}}</p><label>{{t('specialist.scheduleMonth')}}<input type="month" v-model="scheduleMonth"/></label><div v-for="h in datedHours" :key="form.setup.hours.indexOf(h)" :data-date="h.effective_from" class="hour-row"><label>{{t('specialist.workingDate')}}<input type="date" :value="h.effective_from" @change="setWorkingDate(h,($event.target as HTMLInputElement).value)" required/></label><label>{{t('operations.start')}}<input type="time" v-model="h.start" required/></label><label>{{t('operations.end')}}<input :type="h.end==='24:00'?'text':'time'" v-model="h.end" required/></label><button type="button" @click="form.setup.hours.splice(form.setup.hours.indexOf(h),1)">{{t('specialist.removeHours')}}</button><p v-if="dayErrors[h.weekday]" role="alert">{{t('specialist.'+dayErrors[h.weekday])}}</p></div><button type="button" @click="addWorkingDate">{{t('specialist.addWorkingDate')}}</button></section><section v-for="day in days" :key="day.value" class="working-day" :aria-describedby="dayErrors[day.value]?'day-error-'+day.value:undefined"><label class="day-switch"><input type="checkbox" :checked="form.setup.hours.some((h:any)=>h.weekday===day.value&&!isDated(h))" @change="toggleDay(day.value,($event.target as HTMLInputElement).checked)"/>{{day.label}} · {{t(form.setup.hours.some((h:any)=>h.weekday===day.value&&!isDated(h))?'specialist.working':'specialist.notWorking')}}</label><div v-for="hour in form.setup.hours.filter((h:any)=>h.weekday===day.value&&!isDated(h))" :key="form.setup.hours.indexOf(hour)" class="hour-row"><label>{{t('operations.start')}}<input v-model="hour.start" type="time" required :aria-invalid="!!dayErrors[day.value]" :aria-describedby="'day-error-'+day.value"/></label><label>{{t('operations.end')}}<input v-model="hour.end" :type="hour.end==='24:00'?'text':'time'" required :aria-invalid="!!dayErrors[day.value]" :aria-describedby="'day-error-'+day.value"/></label><button v-if="form.setup.hours.filter((h:any)=>h.weekday===day.value&&!isDated(h)).length>1" type="button" @click="form.setup.hours.splice(form.setup.hours.indexOf(hour),1)">{{t('specialist.removeHours')}}</button></div><details v-if="form.setup.hours.some((h:any)=>h.weekday===day.value&&!isDated(h))" class="extra-hours"><summary>{{t('specialist.more')}}</summary><button type="button" @click="addHour(day.value)">{{t('specialist.extraHours')}}</button></details><p v-if="dayErrors[day.value]" :id="'day-error-'+day.value" class="day-error" role="alert">{{t('specialist.'+dayErrors[day.value])}}</p></section><details class="copy-hours"><summary>{{t('specialist.copyHours')}}</summary><p>{{t('specialist.copyHelp')}}</p><label v-for="day in days.filter(d=>d.value!==1)" :key="day.value"><input v-model="copyDays" type="checkbox" :value="day.value"/>{{day.label}}</label><button type="button" :disabled="!copyDays.length||!form.setup.hours.some((h:any)=>h.weekday===1&&!isDated(h))" @click="copyMonday">{{t('specialist.copyApply')}}</button></details></fieldset>
<button v-if="id||tab==='profile'" class="save-changes" type="submit" :disabled="busy||preparing||publication?.busy||(tab==='profile'&&!!form.editorial_key&&!publication?.loaded)||(!id&&tab!=='profile')">{{t(tab==='schedule'?'specialist.saveSchedule':'specialist.save')}}</button></form>
<details v-show="tab==='schedule'" class="absence-options"><summary>{{t('specialist.absenceOptions')}}</summary><AdminSchedulesView v-if="id" :key="id" ref="absence" :doctor-id="id" :working-hours="JSON.parse(baseline).setup.hours" embedded/></details>
<section class="booking-status"><h2>{{t(form.active&&form.booking_enabled?'specialist.enabled':'specialist.disabled')}}</h2><p v-if="!form.booking_enabled">{{t(!eligible?'specialist.selectService':!validHours?'specialist.setHours':!privacy?'specialist.clinicSettings':ready?'specialist.readyEnable':'specialist.setHours')}}</p><p v-if="dirty">{{t('specialist.saveBeforeEnable')}}</p><button type="button" :disabled="busy||(!form.booking_enabled&&dirty)||!id||(!form.booking_enabled&&!ready)" @click="save(!form.booking_enabled)">{{t(form.booking_enabled?'specialist.disable':'specialist.enable')}}</button></section>
</template><dialog ref="picker" @keydown="trapDialogFocus" :aria-label="t('operations.portrait')"><MediaLibrary v-if="picking" picker @select="select" @close="()=>{picking=false;picker?.close()}"/></dialog></section></template>
